using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using CGALPolygon = CGAL::Polygon_2<Kernel>;
using CGALPwh = CGAL::Polygon_with_holes_2<Kernel>;

CGALPolygon cgPoly1, cgPoly2;

// convert first polygon
for (const auto& pt : P1.vectorPoints()) {
    cgPoly1.push_back(Kernel::Point_2(pt.x(), pt.y()));
}

// convert second polygon
for (const auto& pt : P2.vectorPoints()) {
    cgPoly2.push_back(Kernel::Point_2(pt.x(), pt.y()));
}

// ensure counter‑clockwise orientation (required by CGAL Boolean operations)
if (cgPoly1.is_clockwise_oriented())
    cgPoly1.reverse_orientation();
if (cgPoly2.is_clockwise_oriented())
    cgPoly2.reverse_orientation();

// compute difference
std::list<CGALPwh> diffList;
CGAL::difference(cgPoly1, cgPoly2, std::back_inserter(diffList));

// copy results into the required return type
resultVec.reserve(diffList.size());
for (const auto& pwh : diffList) {
    resultVec.emplace_back(pwh);
}
return resultVec;

